struct ConfigReader;
impl ConfigReader {
    pub fn read(path: &str) -> Vec<String> {
        // knows the format: one `key=value` per line, `#` comments
        std::fs::read_to_string(path).unwrap()
            .lines()
            .filter(|l| !l.starts_with('#'))
            .map(str::to_string)
            .collect()
    }
}

struct ConfigParser;
impl ConfigParser {
    pub fn parse(lines: &[String]) -> HashMap<String, String> {
        // knows the format again: split on `=`
        lines.iter()
            .filter_map(|l| l.split_once('='))
            .map(|(k, v)| (k.trim().to_string(), v.trim().to_string()))
            .collect()
    }
}

struct ConfigWriter;
impl ConfigWriter {
    pub fn write(path: &str, map: &HashMap<String, String>) {
        // and a third time: reconstructs `key=value` lines
        let raw: String = map.iter().map(|(k, v)| format!("{k}={v}\n")).collect();
        std::fs::write(path, raw).unwrap();
    }
}
